import SwiftUI
import shared_ui

/**
 * iOS entry-point composable.
 *
 * MainViewController is generated by the Compose Multiplatform framework from
 * the :shared:ui module.  On iOS, CMP wraps the Compose tree in a
 * UIViewController; we embed it here via UIViewControllerRepresentable.
 *
 * NOTE: This file cannot be compiled on Windows. Verify on a macOS machine
 * with Xcode 15+ and the iOS simulator before Phase 3.
 */
struct ContentView: View {
    var body: some View {
        ComposeView()
            .ignoresSafeArea(.keyboard) // Compose handles keyboard insets itself
    }
}

/// Bridges the CMP UIViewController into SwiftUI.
struct ComposeView: UIViewControllerRepresentable {
    func makeUIViewController(context: Context) -> UIViewController {
        // MainViewControllerKt is generated by the Compose compiler plugin.
        // It calls AppRoot() composable from :shared:ui.
        MainViewControllerKt.MainViewController()
    }

    func updateUIViewController(_ uiViewController: UIViewController, context: Context) {}
}
